sys_variable_value.value:
(function execute(inputs, outputs) {
  outputs.skipped_approvals = 0;

  try {
    var regId = '';
    var ref = inputs.base_registration;

    if (ref) {
      if (typeof ref === 'string') {
        regId = String(ref);
      } else if (typeof ref === 'object') {
        regId = String(ref.sys_id || ref.value || ref.display_value || '');
      }
    }
    if (!regId) return;

    var comment = 'Approval automatically skipped because this Base Registration was approved by an Office Manager admin (' +
                  gs.getUserDisplayName() + ').';

    var appr = new GlideRecord('sysapproval_approver');
    appr.addQuery('sysapproval', regId);
    appr.addQuery('state', 'requested');
    appr.query();

    var count = 0;
    while (appr.next()) {
      appr.setValue('state', 'not_required');
      appr.setValue('comments', comment);
      appr.update();
      count++;
    }

    outputs.skipped_approvals = count;

  } catch (e) {
    outputs.error = (e && e.message) ? e.message : String(e);
  }
})(inputs, outputs);

